/**
 * Merge the entries above into the generated tables (in place) and return the
 * list of pairs taken from this file, so property reports can name the source.
 * @param {{PR:object, NRTL:object, UNIQUAC:object}} bip the mb-bip.js default export
 * @returns {{PR:Object<string,string>, NRTL:Object<string,string>, UNIQUAC:Object<string,string>, T:object}} pair → source
 */
export function applyExtra(bip) {
  const used = { PR: {}, NRTL: {}, UNIQUAC: {}, T: { NRTL: {}, UNIQUAC: {} } };
  const nz = (v) => (typeof v === 'number' && isFinite(v) ? v : 0);
  for (const [pair, e] of Object.entries(PR)) {
    if (!e || typeof e.kij !== 'number' || !isFinite(e.kij)) continue;
    bip.PR[pair] = e.kij;
    used.PR[pair] = e.source || 'mb-bip-extra.js';
  }
  for (const [pair, e] of Object.entries(NRTL)) {
    if (!e || typeof e.b !== 'number' || !isFinite(e.b)) continue;
    bip.NRTL[pair] = [e.b, typeof e.alpha === 'number' ? e.alpha : 0.3, nz(e.a), nz(e.e), nz(e.f)];
    used.NRTL[pair] = e.source || 'mb-bip-extra.js';
    if (Array.isArray(e.T)) used.T.NRTL[pair] = e.T;
  }
  for (const [pair, e] of Object.entries(UNIQUAC)) {
    if (!e || typeof e.b !== 'number' || !isFinite(e.b) || !bip.UNIQUAC) continue;
    bip.UNIQUAC[pair] = [e.b, nz(e.a), nz(e.e), nz(e.f)];
    used.UNIQUAC[pair] = e.source || 'mb-bip-extra.js';
    if (Array.isArray(e.T)) used.T.UNIQUAC[pair] = e.T;
  }
  return used;
}

export default { BIP_EXTRA_VERSION, PR, NRTL, UNIQUAC, applyExtra };
